command:
(async () => {
  // 確認宏觸發時 args[0] 存在“on”或“off”
  const hook = args[0];
  const tokenD = canvas.tokens.get(args[1]?.tokenId);
  if (!tokenD) return;

  if (hook === "on") {
    // 效果創建時：立即造成 5d10 力場傷害
    const roll = await new Roll("5d10[force]").roll({async: true});
    await new MidiQOL.DamageOnlyWorkflow(
      actor,
      token,
      roll.total,
      'force',
      tokenD ? [tokenD] : [],
      roll,
      { flavor: "DAE Effect: Force Damage on creation" }
    );
  }
  // hook === "off" 時，無操作
})();
